xpath.script:
(function () {
    'use strict';

    var SK = 'session_start_time';
    var PK = 'nx_session_page_views';
    var VK = 'pricing_visits';

    /* ── Session start ─────────────────────────── */
    var startRaw = sessionStorage.getItem(SK);
    var sessionStart;
    if (!startRaw) {
        sessionStart = Date.now();
        sessionStorage.setItem(SK, sessionStart);
    } else {
        sessionStart = parseInt(startRaw, 10);
    }

    /* ── Page views counter ────────────────────── */
    var pv = parseInt(sessionStorage.getItem(PK) || '0', 10) + 1;
    sessionStorage.setItem(PK, pv);

    /* ── Pricing visits counter ────────────────── */
    var onPricing = window.location.pathname.indexOf('/pricing') !== -1;
    var prv = parseInt(sessionStorage.getItem(VK) || '0', 10);
    if (onPricing) {
        prv += 1;
        sessionStorage.setItem(VK, prv);
    }

    /* ── Update HUD pill ───────────────────────── */
    function updateHUD() {
        var el = document.getElementById('nxPageViews');
        if (el) el.textContent = pv + (pv === 1 ? ' page' : ' pages');

        var sec = Math.floor((Date.now() - sessionStart) / 1000);
        var mm = String(Math.floor(sec / 60)).padStart(2, '0');
        var ss = String(sec % 60).padStart(2, '0');
        var fmt = mm + ':' + ss;

        var t1 = document.getElementById('nxSessionTimer');
        if (t1) t1.textContent = fmt;

        var t2 = document.getElementById('stripDuration');
        if (t2) t2.textContent = fmt + 's';
    }

    /* Run immediately + every second */
    updateHUD();
    setInterval(updateHUD, 1000);

    /* ── Pricing dwell beacon ──────────────────── */
    if (onPricing) {
        var ps = Date.now();
        function beacon() {
            var t = Math.round((Date.now() - ps) / 1000);
            var body = JSON.stringify({jsonrpc:'2.0',method:'call',params:{time_spent:t}});
            if (navigator.sendBeacon) {
                navigator.sendBeacon('/telemetry/pricing', new Blob([body],{type:'application/json'}));
            }
        }
        window.addEventListener('beforeunload', beacon);
        setInterval(beacon, 25000);
    }

    /* ── Billing toggle ────────────────────────── */
    var bm = document.getElementById('btnMonthly');
    var ba = document.getElementById('btnAnnual');
    if (bm && ba) {
        bm.addEventListener('click', function () {
            bm.classList.add('active'); ba.classList.remove('active');
            var ps2 = document.getElementById('priceStarter'); if (ps2) ps2.textContent = '$480';
            var pp = document.getElementById('pricePro'); if (pp) pp.textContent = '$1,480';
        });
        ba.addEventListener('click', function () {
            ba.classList.add('active'); bm.classList.remove('active');
            var ps3 = document.getElementById('priceStarter'); if (ps3) ps3.textContent = '$390';
            var pp2 = document.getElementById('pricePro'); if (pp2) pp2.textContent = '$1,190';
        });
    }

    /* ── FAQ accordion ─────────────────────────── */
    document.querySelectorAll('.nx-faq-trigger').forEach(function (tr) {
        tr.addEventListener('click', function () {
            var it = tr.closest('.nx-faq-item');
            if (it) it.classList.toggle('active');
        });
    });

    /* ── Live JSON terminal sync (demo page) ──── */
    var jPages = document.getElementById('jsonPages');
    var jPrv   = document.getElementById('jsonPricingVisits');
    var jTime  = document.getElementById('jsonTime');
    if (jPages) jPages.textContent = pv;
    if (jPrv)   jPrv.textContent = prv;

    function syncTerminal() {
        var els = [
            ['f_name','jsonName'], ['f_email','jsonEmail'],
            ['f_company','jsonCompany']
        ];
        els.forEach(function(p) {
            var inp = document.getElementById(p[0]);
            var out = document.getElementById(p[1]);
            if (inp && out) out.textContent = JSON.stringify(inp.value);
        });
        var selects = [
            ['f_industry','jsonIndustry'], ['f_role','jsonRole'],
            ['f_size','jsonSize'], ['f_crm','jsonCrm']
        ];
        selects.forEach(function(p) {
            var sel = document.getElementById(p[0]);
            var out = document.getElementById(p[1]);
            if (sel && out) {
                var txt = sel.options[sel.selectedIndex] ? sel.options[sel.selectedIndex].text : '';
                out.textContent = JSON.stringify(txt);
            }
        });
        if (jTime) {
            jTime.textContent = Math.floor((Date.now() - sessionStart) / 1000);
        }
    }

    ['f_name','f_email','f_company'].forEach(function(id) {
        var e = document.getElementById(id);
        if (e) e.addEventListener('input', syncTerminal);
    });
    ['f_industry','f_role','f_size','f_crm'].forEach(function(id) {
        var e = document.getElementById(id);
        if (e) e.addEventListener('change', syncTerminal);
    });

    setInterval(function() {
        if (jTime) jTime.textContent = Math.floor((Date.now() - sessionStart) / 1000);
    }, 1000);

    /* ── Copy JSON button ──────────────────────── */
    var cpBtn = document.getElementById('btnCopyJson');
    if (cpBtn) {
        cpBtn.addEventListener('click', function () {
            var pe = document.getElementById('livePayloadJson');
            if (pe && navigator.clipboard) {
                navigator.clipboard.writeText(pe.innerText).then(function () {
                    cpBtn.textContent = '✓ Copied!';
                    cpBtn.style.background = '#059669';
                    setTimeout(function () { cpBtn.textContent = '📋 Copy Raw JSON for Odoo'; cpBtn.style.background = ''; }, 2000);
                });
            }
        });
    }

    /* ── Report download tracking ─────────────── */
    var rBtn = document.getElementById('downloadReportBtn');
    if (rBtn) {
        rBtn.addEventListener('click', function (ev) {
            ev.preventDefault();
            fetch('/telemetry/report', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({jsonrpc:'2.0',method:'call',params:{}})
            });
            rBtn.innerHTML = '✓ Downloaded'; rBtn.style.background = '#10B981';
            setTimeout(function(){ rBtn.innerHTML = 'Download Report (Free PDF)'; rBtn.style.background=''; }, 3500);
        });
    }

    /* ── Form submission: inject telemetry ─────── */
    var form = document.getElementById('demoArchitectureForm');
    if (form) {
        form.addEventListener('submit', function () {
            var ts = Math.floor((Date.now() - sessionStart) / 1000);
            var ti = document.getElementById('time_on_site');
            var pi = document.getElementById('pricing_page_visits');
            if (ti) ti.value = ts;
            if (pi) pi.value = parseInt(sessionStorage.getItem(VK) || '0', 10);
        });
    }

    /* ── HUD click info ────────────────────────── */
    var hud = document.getElementById('nxTelemetryHud');
    if (hud) {
        hud.style.cursor = 'pointer';
        hud.title = 'Live Telemetry Active';
        hud.addEventListener('click', function () {
            var sec2 = Math.floor((Date.now() - sessionStart) / 1000);
            alert(
                '📡 REVENGINE TELEMETRY HUD\n─────────────────────\n' +
                '• Pages: ' + pv + '\n' +
                '• Session: ' + sec2 + 's\n' +
                '• Pricing Views: ' + prv + '\n' +
                '• CNDP: Validated'
            );
        });
    }
})();

